DNS_record_name.inputs:
@concat('_dnsauth', if(
  equals(items('For_Each_Pending_Domain')?['properties']?['hostName'], parameters('govZoneName')),
  '',
  concat('.', first(
    split(
      items('For_Each_Pending_Domain')?['properties']?['hostName'],
      concat('.', parameters('govZoneName'))
    )
  ))
))
